from __future__ import annotations
from typing import Hashable, Mapping, Sequence, TypeVar

Cut = TypeVar("Cut", bound=Hashable)

def phi(losses: Mapping[Cut, float]) -> tuple[Cut, float]:
    """Return a minimum-loss cut and its loss."""
    if not losses:
        raise ValueError("At least one cut is required")
    if any(value < 0 for value in losses.values()):
        raise ValueError("Losses must be nonnegative")
    cut = min(losses, key=losses.__getitem__)
    return cut, losses[cut]

def exclusion(
    families: Mapping[str, Mapping[Cut, float]]
) -> tuple[float, list[str]]:
    """Compute max_i min_c L_i(c), retaining every tie."""
    if not families:
        raise ValueError("At least one candidate is required")
    scores = {name: phi(losses)[1] for name, losses in families.items()}
    value = max(scores.values())
    return value, [name for name, score in scores.items() if score == value]
